  VALUES 
    (462::BIGINT, 'Muy buena gente la profe y ayuda mucho con dudas durante exámenes y el proyecto, aunque son largas y aburridas las clases explica lo necesario, el proyecto es muy largo eso si es bueno trabajarlo apenas lo deje, super servicial y hay que extender fechas de entrega con los trabajos y examen lo hace.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '3fd5d4911ded9b4bb9a5f40be7177fb0b435cbc53a07cc7305a5de157a2d9f58'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Nunca he entendido a los profes que toman estos cursos de 2 créditos, y los convierten en cursos de 4, jodiendole a uno el semestre. Esta profe es pura vida, ya que es todo lo contrario. Si ud tiene un buen grupo, el curso se pasa fácil. Y la profe siempre brinda apoyo con los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'bea02152da9377d734cf0c1bde8d6ce928fffb2130c4ef2718db4e32aec71af3'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'La profesora es algo confusa con las evaluaciones y a veces algo desordenada. Las clases son un sueño porque pasa leyendo diapositivas y la materia no es muy entretenida. Hay bastantes trabajillos, por lo que hay que buscar un buen equipo. Los exámenes y quices son en Excel y en grupo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f7a12e1297dbe39659affd55c3c4c78ba85952df94e65bb069c883db550a4b49'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'La profe es muy buena persona, muy comprensiva con las fechas, la clase es aburrida pero por la materia en sí, las evaluaciones son fáciles y hace el curso bastante sencillo de pasar, los trabajos son todos grupales así que si tiene buen grupo se hace un curso fácil incluso sin saber mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, '95c5bf1a5d3031a19925410ccbd719d3632406310a21fa947670e19665ea3998'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'La profe es muy buena persona y muy comprensiva, el curso en sí es aburrido pero ella se encarga que todos logremos entender, todo es grupal entonces lo hace menos denso, los exámenes son sencillos y califica suave, en sí ella es muy linda como persona la recomiendo totalmente :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1081b8c10bcf71d8e8f0d668e86444ed7070bc0c8de77c354eff0bba1924cd13'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'El curso en general es aburrido. La profe es buena gente pero quizás puede ser que la metodología de la clase haga que sea algo cansado, diría que la recomiendo porque en si es buena profe.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8e716e6ce2ca29af7848400b1f81ce508f23799573ee28720e46f5961a3a556a'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'La profe explica regular, las instrucciones de los exámenes y proyectos son complicados, pero ella ayuda en todo lo que pueda, es fácil de pasar pero se pierde el interés en la clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd52ee268d3115a2c6bf59cd09007b29380b652f3dd2f7163fd63fc884fc3134a'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Muy buena profe, explica bien y ayuda bastante si uno no entiende algo. A veces las instrucciones de las evaluaciones son un poco confusas pero si uno le pregunta le explica bien'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9b4dfd4eee89d613d77fc2f4d421e8103615f43b62926e9f84e55bae587372ff'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'El curso se pasa solo, la profe es buena nota y en general, super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '83b9753d6fce288286aeee33d2b822a189c391372f307af31060d3e0becb07d7'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'La profe es un amor de persona y el curso de pasa super facil con entregar los trabajos y hacerlos a conciencia. Es un poco desordenada con algunas cosas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e6c8ab85978a89b5482f182520da641eca6ae1ca3e0ce34020d5f1017dac80b0'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'No sean creativos, solo hagan las cosas a cómo ella diga. No deja instrucciones claras, y hace trabajos muy enredados.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-05-04T00:00:00+00:00'::TIMESTAMPTZ, '9fcc1a9ecd03c52d2a496a02d28329b13a7fefd8b57dbd958d488cbcfa1c57dd'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'Muy buena profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '641d4cb71e0a158cc393c3fb8404416c4ac966366c046024b315cd95e12191e4'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'La profesora es muy buena persona, está muy dispuesta a ayudar, la materia puede ser un poco confusa, por eso es importante poner atención en clase, por lo demás, se pasa fácil, exámenes grupales, proyecto final es largo pero ella ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'a449b8b1ed5bda271eb41df19432bb1da60350599e23b07c18caa96d3230b2f5'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Le cuesta explicar, da pocos ejemplos en vivo. Pero los exámenes no fueron tan duros. Teja asegurada si cumple con todo lo que pide.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '024ce4b3ecd8b26bba5ac117804de1e170f1e0bd4c14e1ce86b54033bf8e0d03'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Las clases son muy poca ayuda, es complicado entenderle la materia, debido a que no deja instrucciones claras, además para lo exámenes y demás evaluaciones que deje, tenga presente que ella las saca de internet, de nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'b6ab04c6875d48cf3318fa5a49a5c685cfb970030b9a7bfb85f4a7c544b4b219'::TEXT, ARRAY[1728]::BIGINT[]),
    (462::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'b321cacdc5c6408961bf5248dfa842ce2b5b8bd8419ec6b9e85fcbf67990f41c'::TEXT, ARRAY[1746]::BIGINT[]),
    (462::BIGINT, 'Meta sin miedo, ella es un sol, solo que un poco desordenada. El curso es muy accesible y entretenido algunos temas. A mi parecer deja muchas tareas y trabajos, pero igual son fáciles. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '47a643d9b26b39d5f0038a8980d7c0027d3be324a6d55a2e716dfe7934b966b7'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'La profe es excelente e intenta hacer el curso interesante, pero es bastante difícil si a uno no le llama la atención el tema. Ayuda mucho para el proyecto y los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'f6dd0694da74ddf1a354c5fbbc3498677404448104d3578941ea0668cdf209fe'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Excelente profesora. Atiende consultas y ayuda mucho para el proyecto grupal. Hace ejercicios que ayudan mucho para los dos exámenes. Trata de que uno entienda bien los conceptos durante las clases. Evalúa bien y las rúbricas son claras.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'bb3c57fcd77590f07b6530309bf7a35ce20f80ed5d1dfdeaa7b62320f38159a7'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'No es muy clara al explicar, da ejemplos muy simples que vienen en el libro, los exámenes suelen ser un caso y casi todas las semanas hay quiz pero sencillos. El curso se pasa fácil pero no de aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '1fc8e4415ff89a9893641954d0de99e99de326a9ac04f9853e1465324f6e7bd9'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (462::BIGINT, 'La profe es super amable y siempre trata de que uno entienda y se lo pase bien en la clase . Todos los trabajos son en grupo y la clase trata que sea lo más dinámica posible con las actividades , pero 4 h de clases aveces se vuelve bastante pesado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'fdee7c36d55f388365f7cd81e507598d37ac82ecd9ed624c6cb470e6875f087d'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'En modalidad virtual creo que deja demasiadas cosas. Uno llega pensando que va a ser de los cursos más relajados pero por el tiempo que termina invirtiendo, no lo es. La profe es muy buena gente, y de verdad se esfuerza, pero las clases se vuelven muy pesadas y largas. Se pasa con buena nota.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-02-25T00:00:00+00:00'::TIMESTAMPTZ, '8649e482fa7aae6c6d144c9f27ced66a7025e0b45b16ea0e27e475d2228dad4e'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, '(virtual) el curso es demasiado facil pero si deja DEMASIADAS tareas, se hacen rápido pero hay que sacar el tiempo. Las clases duran hasta más de la hora límite. La materia es bonita y la profe es demasiado buena gente'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '7a8b995afe90e1848a1344b699bb8cae1cc94928a4f1b5172a213241bb95a182'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'Excelente, ayuda mucho para el proyecto, se pone las pilas para que todo mundo entienda (tiene demasiadaaa paciencia diría yo), buena gente, a todo el mundo atiende cuando se trata de consultas y los exámenes se pasan si presta atención a las clases. Resuelve ejercicios del nivel de los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '4bab4a31133f7ee8c5a73b156dd571af3f6208537b18e9b9260b7cd219111d62'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Prácticamente los estudiantes dan el curso, se hace un taller de un tema y se presenta uno por semana, el resto es hacer un caso que se entrega la semana siguiente. El curso ni se siente, la profe es cosi, pero con un mal manejo del tiempo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'd4f3c4560cf8453bcfd9468a4115a0c871b392ea1cf5be4ed190aeb718472c53'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'Buena profesora, explica bien. Las diapositivas tienen mucho contenido que no se ve, hace bastante práctica dentro de las clases. Las clases no son tan largas. Quices normales y ayuda mucho con el proyecto para que uno salga lo mejor posible. Siempre está atenta a despejar dudas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e97c28c6ae2a8f528c8a91fbb76a25f62219328caf75306a892976ef7a22a424'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'fbd519b87c0acfa45086ba9c00b1050572b54bbc78c4086d149ed9fda75c9b7a'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Comprometida en ayudar a los estudiantes sin embargo sus lecciones pueden ser de hasta 4 horas seguidas por lo que las hace tediosas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'f3bf66601383d3486ba221a02bf3047f4d508a5b0ed9ae6cdc9c8a26bb10aae6'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'En general es buena profe, las clases virtuales se hacen eternas, en el proyecto hay que trabajar bastante, examenes en grupo y con un dia de tiempo para hacerlo. Lo mejor es hacer las cosas con tiempo, ella es muy accesible y siempre le ayuda a uno en lo que ocupe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '2a8ec165bba3b38d0eeedc44f92f0ad9d2e87284bab93c27f2b035115d07e78c'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Es buena para este curso, porque hace casos prácticos de negociación o comunicación, lo cual es mejor que hacer un examen, porque uno aplica lo que le enseñan. Ve cosas del currículum interesantes. Tiene un tono aburrido, clase dura aprox 3 horas. No hay examenes. Es fácil.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a36ec8c6d9a2892d4dc484411e6383daa97dbad582adc2909f32e4580081dccb'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'Mil veces mejor que el otro mae que da el mismo curso, por lo que he escuchado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '755707e9293bce92751c45c2670e3fc84db6851a27acbdc161b323565d381a2b'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'La mejor, nos da casos reales y se aprende haciendo, los que no aprenden es porque no les gusta esforzarse. Hay que leer antes eso si.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2020-02-20T00:00:00+00:00'::TIMESTAMPTZ, '1b4382ee4501cd9f1d4f28242b567af2b4f785bd5f3cbd74c391eee98f332dd1'::TEXT, ARRAY[1760]::BIGINT[]),
    (462::BIGINT, 'Usa mucho el tec digital con muchas instrucciones , deja material con soluciones, busca que aprendamos con ejemplos de la industria y casos reales aunque muchos compañeros salen a cada rato de clases para hacer trabajos de otros cursos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '78c10982d4f8c3200b7cad4cbab22e5a5a39d3f3307c7817e496465a15a6aaca'::TEXT, ARRAY[1728]::BIGINT[]),
    (462::BIGINT, 'La profe solo llega a leer diapositivas que se nota que no son hechas por ella, se enreda explicando los mismo ejemplos que aparecen resueltos en la diapositivas por lo cual la clase se vuelve un poco aburrida y cuesta quedar claro con la materia en clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3388b68b784c7f6ff43e7f723eb149f73733a3b6c0a7abff13994579a439e25'::TEXT, ARRAY[1728]::BIGINT[]),
    (462::BIGINT, 'Es la mejor opción ! , casi no deja nada , solo hay que ir, hacer alguna actividad, y escuchar al grupo que le toque exponer(siempre hay merienda al final), al final se va a una empresa a exponer, hay mucho feedback en las actividades y exposiciones'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9086a6e10e8dd90e78f894b29df885d514aea0e6c57ab0851834b1574b286af2'::TEXT, ARRAY[1312]::BIGINT[]),
    (462::BIGINT, 'La profesora no sabe explicar la materia y califica muy rudo. Las clases son extremadamente aburridas donde pasa presentaciones de pp con ejercicios resueltos los cuales explica muy por encima. Es la opción más aceptable para el curso, pues al menos como persona es un sol.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c6cad52e71c235cacf4898c5017497ed6ae5fca533d366c7aacc9fc54f416161'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Es un amor de persona y ayuda mucho en los exámenes, es muy atenta con las dudas y tiene mucha paciencia. De ahí todo lo demás es fatal, evalúa súper duro y cuesta entenderle la materia. Muchas de las evaluaciones son sumamente complicadas por esta misma razón.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8b653e5551a3701002b787a1cd529cb6ff67b392eee35d3c68e1208f8c199384'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Demasiado aburrida y no sabe mucho de la matemática que aplica por lo que es confuso y si se equivoca es muy difícil hacerla entrar en razón. Pero la materia es fácil, los exámenes pasables y lo que escucho de los demás profesores no es mejor. No acepten "Retos".'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd0563579d05289271e21a29cf241a7b221739a1aad2a15d64dc0e8c707e75960'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Solamente lee diapositivas y muchas veces no logró evacuar dudas de los ejercicios. Pero siempre está dispuesta a ayudar y no hace el curso tan demandante, aunque los exámenes son difíciles y ella califica un poco fuerte.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b46c3767f2e1170e9aae00ae143216994fd0574f147390037ad54b41f19b1f35'::TEXT, ARRAY[1298]::BIGINT[]),
    (462::BIGINT, 'Las clases son muy aburridas porque solo lee diapositivas pero en general no es lo peor. El primer examen fue muy largo y rudo mientras que el segundo fue un regalo. Revisa fuerte.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '6f3edcca2c6f2daabe43a4d104106095ba5a6c8071d292468f6cd5c68c4cdff1'::TEXT, ARRAY[1728, 1743, 1742]::BIGINT[]),
    (462::BIGINT, 'La profe es supeeeeer buena nota y super buena persona, las clases suelen ser un poco aburridas, para los examenes hay que estudiar, no deja quices (solo tareas) y califica un poco rudillo, pero es un curso que si se pasa'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '3e8e2036889f61ce183e6b2b8d9d11a28e1b3419f3748247575d5331ec7fb4ac'::TEXT, ARRAY[1728, 1743, 1742]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
